<?php
namespace Tests\Feature;use App\Models\NewsArticle;use App\Models\User;use App\Services\VideoScriptGenerator;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Http;use Tests\TestCase;
class VideoScriptTest extends TestCase{use RefreshDatabase;
 public function test_ai_script_has_scenes_teleprompter_duration_and_never_auto_approves():void{$user=User::factory()->create();$article=NewsArticle::create(['author_id'=>$user->id,'title'=>'Obra é anunciada','slug'=>'obra-anunciada','excerpt'=>'Prefeitura anunciou uma obra que ainda será licitada.','body'=>'Informações oficiais da matéria.','status'=>'draft']);config(['luzicity.ai.openai_api_key'=>'test']);Http::fake(['https://api.openai.com/v1/chat/completions'=>Http::response(['choices'=>[['message'=>['content'=>json_encode(['title'=>'Roteiro da obra','teleprompter_text'=>'Texto revisável para apresentação.','editorial_notes'=>'Confirmar cronograma.','scenes'=>[['title'=>'Abertura','narration'=>'Obra anunciada.','visual'=>'Apresentador','duration_seconds'=>20]]])]]]],200)]);$script=app(VideoScriptGenerator::class)->generate($article,60,$user->id);$this->assertSame('pending_review',$script->status);$this->assertSame('openai',$script->provider);$this->assertNotEmpty($script->scenes);$this->assertNotEmpty($script->teleprompter_text);$this->assertNull($script->reviewed_at);}
}
